-- ------------------------------------------------------------
-- Table: products
-- ------------------------------------------------------------

CREATE TABLE `products` (
  `id`               bigint UNSIGNED  NOT NULL AUTO_INCREMENT,
  `sku`              varchar(255)     NOT NULL,
  `barcode_type`     varchar(255)     NOT NULL DEFAULT 'TYPE_CODE_128',
  `name`             varchar(255)     NOT NULL,
  `description`      text             DEFAULT NULL,
  `transaction_type` enum('BORROW','REQUEST') DEFAULT NULL,
  `value`            decimal(10,2)    DEFAULT NULL,
  `image`            varchar(255)     DEFAULT NULL,
  `images`           json             DEFAULT NULL,
  `category_id`      bigint UNSIGNED  DEFAULT NULL,
  `location_id`      bigint UNSIGNED  DEFAULT NULL,
  `position_image`   varchar(255)     DEFAULT NULL,
  `current_stock`    int              NOT NULL DEFAULT '0',
  `initial_stock`    int              NOT NULL DEFAULT '0',
  `unit_id`          bigint UNSIGNED  DEFAULT NULL,
  `is_returnable`    tinyint(1)       NOT NULL DEFAULT '1',
  `min_stock`        int              NOT NULL DEFAULT '0',
  `created_at`       timestamp        NULL DEFAULT NULL,
  `updated_at`       timestamp        NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_sku_unique` (`sku`),
  KEY `products_category_id_foreign` (`category_id`),
  KEY `products_location_id_foreign` (`location_id`),
  KEY `products_unit_id_foreign` (`unit_id`),
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `products_location_id_foreign` FOREIGN KEY (`location_id`) REFERENCES `locations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `products_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=434;

